import{z as o,x as B,o as e,c as l,q as r,j as s,D as E,d as i,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"静态与动态险象","description":"","frontmatter":{"title":"静态与动态险象","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/static-dynamic-hazard.md","filePath":"cs/static-dynamic-hazard.md","lastUpdated":1791063341000}'),d={name:"cs/static-dynamic-hazard.md"};function p(c,a,h,D,_,m){const t=B("Mermaid");return e(),l("div",null,[a[2]||(a[2]=r('<h1 id="静态与动态险象" tabindex="-1">静态与动态险象 <a class="header-anchor" href="#静态与动态险象" aria-label="Permalink to &quot;静态与动态险象&quot;">​</a></h1><div class="epigraph"><p>真值表只看起止取值；路径延迟不同，中间可以闪一下。静态险象是不该变却闪，动态险象是该变一次却闪了三次。</p><footer>—— 据 Unger 对组合险象的处理；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/dont-care-hazard">不完全指定与险象</a>钉死了 \\(X\\) 可并入圈，并给出静态 1-险象：相邻两个 \\(1\\) 分属两圈时输出可能短暂变 \\(0\\)。本课不重讲无关项语义，也不从触发器另起。缺口是：险象还只开了一条缝。静态 \\(0\\)、以及输出<strong>应当</strong>翻转时的动态毛刺，没有命名；多级门之后，「加一个覆盖圈」不够用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单输入变化，起点终点都是 \\(1\\)，中间出现 \\(0\\)：静态 1-险象。对偶地，起止都是 \\(0\\)、中间闪 \\(1\\)：静态 0-险象，用 POS 侧的共识项或盖住相邻 \\(0\\) 的圈消除。缺口还包括<strong>动态险象</strong>：起止不同（例如 \\(0\\to 1\\)），但路径上出现 \\(0\\)-\\(1\\)-\\(0\\)-\\(1\\)，三次沿。它往往来自静态险象叠在多级延迟上，单靠两级 SOP 的「相邻 \\(1\\) 共圈」不能一次扫清。</p><p>四类输出波形放在一起看，差别就一目了然。</p>',6)),(e(),s(n,null,{default:E(()=>[A(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%9C%9F%E6%9C%9B%3A%201%20%E4%BF%9D%E6%8C%81%201%22%5D%20--%3E%20B%5B%22%E9%9D%99%E6%80%811%E9%99%A9%E8%B1%A1%3A%201%20%E9%97%AA%200%20%E5%86%8D%E5%9B%9E%201%22%5D%0A%20%20C%5B%22%E6%9C%9F%E6%9C%9B%3A%200%20%E4%BF%9D%E6%8C%81%200%22%5D%20--%3E%20D%5B%22%E9%9D%99%E6%80%810%E9%99%A9%E8%B1%A1%3A%200%20%E9%97%AA%201%20%E5%86%8D%E5%9B%9E%200%22%5D%0A%20%20E%5B%22%E6%9C%9F%E6%9C%9B%3A%200%20%E7%BF%BB%E5%88%B0%201%22%5D%20--%3E%20F%5B%22%E5%8A%A8%E6%80%81%E9%99%A9%E8%B1%A1%3A%200%201%200%201%20%E8%BF%9E%E9%97%AA%22%5D%0A%20%20G%5B%22%E6%9C%9F%E6%9C%9B%3A%201%20%E7%BF%BB%E5%88%B0%200%22%5D%20--%3E%20H%5B%22%E5%AF%B9%E5%81%B6%3A%201%200%201%200%20%E8%BF%9E%E9%97%AA%22%5D%0A%20%20B%20--%3E%20FIX%5B%22%E5%85%B1%E8%AF%86%E9%A1%B9%20%2F%20%E5%AF%B9%E5%81%B6%E8%A6%86%E7%9B%96%22%5D%0A%20%20F%20--%3E%20FIX%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">直觉类比：把每条门路径想成一条长度不同的接力赛道——同一支接力队（同一输入变化）沿两条赛道跑，快的那条先到终点，慢的那条晚几纳秒才把结果改过来，中间就闪出毛刺。稳态下两条路结果一致，真值表完全正确，但交接瞬间可以错。</span></p><p>本课假定输入不同时翻转（基本险象）。多输入同时变的功能险象，有的无法用额外门消去，要靠后课状态编码或采样。</p><h3 id="毛刺不是「逻辑算错」" tabindex="-1">毛刺不是「逻辑算错」 <a class="header-anchor" href="#毛刺不是「逻辑算错」" aria-label="Permalink to &quot;毛刺不是「逻辑算错」&quot;">​</a></h3><p>稳态下输出符合真值表。险象是延迟模型上的瞬态。仿真若只在输入稳定后取样，看不见它；接到时钟敏感点才有害——<a href="/cs/setup-hold">建立保持</a>再定量。</p><p><span class="marginnote">Unger 区分静态 / 动态 / 本质险象。Harris 用卡诺图消静态 1-险象。本课把静态 0 与动态补全，组合手算到此收束；下一课改用集合语言。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>静态 1：差一位的两个最小项须被同一乘积项覆盖（共识项 \\(xy+x\\bar y=x\\)）。静态 0：对偶地覆盖相邻最大项。动态：先消掉会向后传播的静态险象，并检查每条从输入到输出的反相次数；本课不把完整充分条件写成定理，只要求：多级电路要单独查瞬态，不能只信两级覆盖。</p>',7)),(e(),s(n,null,{default:E(()=>[A(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E9%9D%99%E6%80%81%201%EF%BC%9A1%20%E9%97%AA%200%22%5D%20--%3E%20CONS%5B%22%E5%85%B1%E8%AF%86%E8%A6%86%E7%9B%96%22%5D%0A%20%20S0%5B%22%E9%9D%99%E6%80%81%200%EF%BC%9A0%20%E9%97%AA%201%22%5D%20--%3E%20DUAL%5B%22%E5%AF%B9%E5%81%B6%E8%A6%86%E7%9B%96%22%5D%0A%20%20DYN%5B%22%E5%8A%A8%E6%80%81%EF%BC%9A%E7%BF%BB%E8%BD%AC%E9%80%94%E4%B8%AD%E8%BF%9E%E9%97%AA%22%5D%20--%3E%20MULTI%5B%22%E5%A4%9A%E7%BA%A7%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20CONS%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9B%86%E5%90%88%E4%B8%8E%E5%85%B3%E7%B3%BB%22%5D%0A%20%20DUAL%20--%3E%20LATER%0A%20%20MULTI%20--%3E%20LATER%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课组合输出若只在时钟沿被采样，毛刺可能被忽略；异步置位、锁存器透明窗、时钟门控则不能忽略。本课不引入这些元件，只承认瞬态存在。译码器把 \\(X\\) 收进圈之后，相邻关系变了，险象分析必须用<strong>实现后</strong>的式，不能用原来的 \\(X\\) 图。</p><p><span class="marginnote">常见误区：初学者容易以为仿真波形里有毛刺就是电路坏了。实际上只要毛刺不落在时钟采样沿附近，或输出本来只在沿上被读，它就是无害的瞬态；真正要处理的是毛刺恰好被触发器或异步逻辑接住的情形。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析模拟中间电压、不把本质险象（与状态编码纠缠）写完。器件延迟数值从<a href="/cs/cmos-inverter">CMOS</a>才开始。信息与离散课序在下一课换成集合。</p><p>后课默认：静态险象用冗余覆盖消；动态险象要查多级路径。若输出被时钟采样，组合毛刺是否有害另判。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>静态 1 / 0 是起止相同却闪一下；用共识或对偶覆盖消。</li><li>动态险象是该翻一次却连闪，多出现在多级延迟。</li><li>稳态真值表看不见毛刺；组合手算化简到此结束。</li><li>出处：Unger；Harris and Harris。</li></ul>',8))])}const C=o(d,[["render",p]]);export{F as __pageData,C as default};
